$ErrorActionPreference='Stop'
$j=Join-Path $env:TEMP ('smiot-inspect-' + [guid]::NewGuid().ToString('N') + '.json')
$py='import os,json; from dotenv import load_dotenv; load_dotenv("/etc/smiot/app.env"); from service.mongodb_store import collection; ids=["INC-SMIOT-SCENARIO-4A56E662551417AF"]; c=collection("operational_incidents"); print(json.dumps([{ "incident_id":i, "doc":(lambda d:{"status":d.get("status"),"kind":d.get("kind"),"farm_key":d.get("farm_key"),"timeline":d.get("timeline",[]),"details":d.get("details",{}),"recovery_verification":d.get("recovery_verification")} if d else None)(c.find_one({"_id":i}))} for i in ids],default=str))'
$cmds=@('set -e','cd /opt/smiot','export PYTHONPATH=/opt/smiot',"/opt/smiot/.venv/bin/python -c '$py'")
(@{commands=$cmds}|ConvertTo-Json -Compress)|Set-Content -Encoding ascii $j
$id=(aws ssm send-command --profile aws-moi --region ap-southeast-2 --instance-ids i-00bf2d3591d3ee0a2 --document-name AWS-RunShellScript --parameters file://$j --comment 'SMIOT inspect specialized Mongo evidence' --query Command.CommandId --output text).Trim(); do {Start-Sleep 3;$r=aws ssm get-command-invocation --profile aws-moi --region ap-southeast-2 --command-id $id --instance-id i-00bf2d3591d3ee0a2 --output json|ConvertFrom-Json;if($r.Status -in @('Success','Failed','Cancelled','TimedOut')){Write-Output $r.StandardOutputContent;if($r.Status -ne 'Success'){Write-Output $r.StandardErrorContent};break}}while($true); Remove-Item $j -Force -ErrorAction SilentlyContinue
